page_settings.custom_css:
/* Mijn account: dezelfde opbouw als winkelwagen en afrekenen (grijze vlakken, witte velden, knop in accentkleur).
   Staat als Pagina-CSS in Elementor (Pagina-instellingen > Aangepaste CSS); "selector" is deze pagina.
   !important waar de standaardstijl van het widget anders voorgaat. */
selector .elementor-widget-woocommerce-my-account .woocommerce-form-login,
selector .elementor-widget-woocommerce-my-account .woocommerce-form-register,
selector .elementor-widget-woocommerce-my-account .woocommerce-ResetPassword {
	background: #f6f6f6 !important; border: 0 !important; border-radius: 10px !important;
	padding: 28px 32px !important; margin: 0 auto !important; max-width: 560px;
}
/* de paginakop zegt al "Mijn account" */
selector .elementor-widget-woocommerce-my-account .e-my-account-tab > .woocommerce > h2 { display: none; }
selector .elementor-widget-woocommerce-my-account .woocommerce form .form-row label {
	font-family: aptos, sans-serif; font-size: 14px; color: var(--e-global-color-primary) !important;
}
selector .elementor-widget-woocommerce-my-account .woocommerce form .form-row .input-text {
	background: #fff !important; border: 1px solid #e3e3e3 !important; border-radius: 8px !important;
	padding: 12px 14px !important; font-family: aptos, sans-serif;
}
selector .elementor-widget-woocommerce-my-account .woocommerce form .form-row .input-text:focus { border-color: var(--e-global-color-accent) !important; outline: none; }
selector .elementor-widget-woocommerce-my-account .woocommerce button.button,
selector .elementor-widget-woocommerce-my-account .woocommerce .woocommerce-form-login__submit,
selector .elementor-widget-woocommerce-my-account .woocommerce .woocommerce-Button {
	background: var(--e-global-color-accent) !important; color: #fff !important; border: 0 !important;
	border-radius: 8px !important; padding: 12px 28px !important; font-family: aptos, sans-serif !important; font-weight: 700 !important;
	text-transform: none !important;
}
selector .elementor-widget-woocommerce-my-account .woocommerce button.button:hover { background: var(--e-global-color-primary) !important; }
selector .elementor-widget-woocommerce-my-account .woocommerce-form-login__rememberme { display: inline-flex; align-items: center; gap: 8px; margin: 0 16px; }
selector .elementor-widget-woocommerce-my-account .lost_password { margin-top: 12px; font-size: 14px; }
selector .elementor-widget-woocommerce-my-account .lost_password a,
selector .elementor-widget-woocommerce-my-account .woocommerce a { color: var(--e-global-color-accent) !important; }
/* ingelogd: menu links als lijst met vlakken, inhoud rechts */
selector .woocommerce-MyAccount-navigation ul { list-style: none; margin: 0; padding: 16px !important; background: #f6f6f6; border-radius: 10px; }
selector .woocommerce-MyAccount-navigation li a { display: block; padding: 10px 14px; border-radius: 8px; color: var(--e-global-color-text) !important; }
selector .woocommerce-MyAccount-navigation li.is-active a,
selector .woocommerce-MyAccount-navigation li a:hover { background: #fff; color: var(--e-global-color-accent) !important; }
selector .woocommerce-MyAccount-content { font-family: aptos, sans-serif; }
selector .woocommerce table.shop_table { border: 0; background: #f6f6f6; border-radius: 10px; overflow: hidden; }
